function ReaderText({content,editable,onChange,onSelect}:{content:DocumentContent;editable:boolean;onChange:(c:string)=>void;onSelect:(s:{start:number;end:number;quote:string})=>void}){const ref=useRef<HTMLDivElement>(null);const handleMouseUp=()=>{const sel=window.getSelection();if(!sel||sel.isCollapsed||!ref.current?.contains(sel.anchorNode))return;const quote=sel.toString().trim();if(!quote)return;const text=ref.current.innerText;const start=text.indexOf(quote);if(start>=0)onSelect({start,end:start+quote.length,quote})};if(editable)return <CodeMirrorEditor value={content.content} onChange={onChange} onMouseUp={handleMouseUp}/>;return content.summary.format==="md"?<div ref={ref} className="reader-text md-render" onMouseUp={handleMouseUp} dangerouslySetInnerHTML={{__html:DOMPurify.sanitize(marked.parse(content.content,{breaks:true}) as string)}}/>:<div ref={ref} className="reader-text" onMouseUp={handleMouseUp}>{content.content}</div>}
function PaperHeading({kicker,copyKicker=false,content,onOpenTags,onSearchTag}:{kicker:string;copyKicker?:boolean;content:DocumentContent;onOpenTags:()=>void;onSearchTag:(tag:string)=>void}){const copy=async()=>{if(!copyKicker)return;try{await navigator.clipboard.writeText(kicker);toast.success("文件路径已复制")}catch{toast.error("复制失败，请重试")}};return <div className="paper-heading">{copyKicker?<button className="paper-kicker paper-path" title={`${kicker}\n点击复制完整路径`} onClick={copy}>{kicker}</button>:<div className="paper-kicker">{kicker}</div>}<div className="paper-heading-tags">{content.summary.tags.map(tag=><button key={tag} title={`筛选标签 #${tag}`} onClick={()=>onSearchTag(tag)}>#{tag}</button>)}<button className="paper-heading-add" title="管理标签" aria-label="管理标签" onClick={onOpenTags}><Tag size={11}/></button></div></div>}


function SelectionBar({quote,onAnnotate,onMaterial,onClose}:{quote:string;onAnnotate:()=>void;onMaterial:()=>void;onClose:()=>void}){return <div className="selection-bar"><span>已选 {quote.length} 字</span><q>{quote.slice(0,56)}{quote.length>56?"…":""}</q><button onClick={onAnnotate}><Highlighter size={14}/>批注</button><button onClick={onMaterial}><Bookmark size={14}/>摘抄</button><button className="icon-btn" onClick={onClose}><X size={14}/></button></div>}
function AnnotationDialog({marker,setMarker,note,setNote,onSave,onClose}:{marker:string;setMarker:(s:string)=>void;note:string;setNote:(s:string)=>void;onSave:()=>void;onClose:()=>void}){return <div className="modal-backdrop"><div className="modal"><div className="modal-head"><div><span>对标记录</span><h2>给这段文字留个记号</h2></div><button className="icon-btn" onClick={onClose}><X size={16}/></button></div><label>标记类型<select value={marker} onChange={e=>setMarker(e.target.value)}>{markerOptions.map(x=><option key={x}>{x}</option>)}</select></label><label>批注<textarea value={note} onChange={e=>setNote(e.target.value)} placeholder="记录这段文字为什么有效…" autoFocus/></label><div className="modal-actions"><button className="subtle-btn" onClick={onClose}>取消</button><button className="primary-btn" onClick={onSave}>保存批注</button></div></div></div>}
function MaterialsDialog({materials,onClose,onOpen}:{materials:MaterialClip[];onClose:()=>void;onOpen:(id:string)=>void}){return <div className="modal-backdrop"><div className="modal wide"><div className="modal-head"><div><span>素材临时库</span><h2>摘下来的句子</h2></div><button className="icon-btn" onClick={onClose}><X size={16}/></button></div><div className="material-list">{materials.length===0?<div className="modal-empty">选中正文后点击摘抄，这里会留下可跳转的原文片段。</div>:materials.map(x=><button key={x.id} className="material-card" onClick={()=>{onOpen(x.documentId);onClose()}}><q>{x.quote}</q><span>{x.sourceTitle} · {x.groupName}</span></button>)}</div></div></div>}
function SettingsDialog({settings,pageReading,anchor,onPreview,onSave,onClose}:{settings:UserSettings;pageReading:boolean;anchor:DOMRect;onPreview:(settings:UserSettings,pageReading:boolean)=>void;onSave:(s:UserSettings,pageReading:boolean)=>void;onClose:()=>void}){const [draft,setDraft]=useState(settings);const [paged,setPaged]=useState(pageReading);const reader=draft.reader;const panelWidth=Math.min(370,window.innerWidth-24);const left=anchor.left>=panelWidth+20?anchor.left-panelWidth-10:Math.min(window.innerWidth-panelWidth-12,anchor.right+10);const top=Math.max(12,Math.min(window.innerHeight-572,anchor.top-18));const style={left,top,width:panelWidth} as CSSProperties;const update=(next:UserSettings,nextPaged=paged)=>{setDraft(next);setPaged(nextPaged);onPreview(next,nextPaged)};const setReader=(patch:Partial<UserSettings["reader"]>)=>update({...draft,reader:{...reader,...patch}});const setPageMode=(value:boolean)=>update(draft,value);const close=()=>onClose();useEffect(()=>{const key=(event:KeyboardEvent)=>{if(event.key==="Escape")close()};window.addEventListener("keydown",key);return()=>window.removeEventListener("keydown",key)},[]);const fontSize=Math.round(reader.fontSize);const brightness=Math.round(Math.max(.4,Math.min(1,reader.brightness||1))*100);const themes:[Theme,string][]=[["day","日间"],["protect","护眼"],["parchment","羊皮纸"],["night","夜间"]];return <div className="settings-flyout-layer" onMouseDown={close}><section className="settings-flyout" style={style} onMouseDown={event=>event.stopPropagation()} aria-label="阅读设置"><header className="settings-head"><div><span>阅读偏好</span><h2>设置</h2></div><button className="icon-btn" title="关闭并取消更改" onClick={close}><X size={15}/></button></header><div className="settings-rows"><div className="settings-row"><span className="settings-label">主题</span><div className="theme-swatches">{themes.map(([value,label])=><button key={value} className={`theme-swatch swatch-${value} ${reader.theme===value?"active":""}`} title={label} aria-label={label} aria-pressed={reader.theme===value} onClick={()=>setReader({theme:value})}>{reader.theme===value&&<span>✓</span>}</button>)}</div></div><div className="settings-row"><span className="settings-label">亮度</span><div className="brightness-control"><Moon size={14}/><input type="range" min={40} max={100} step={1} value={brightness} style={{"--range-value":`${(brightness-40)/60*100}%`} as CSSProperties} aria-label="阅读亮度" onChange={e=>setReader({brightness:Number(e.target.value)/100})}/><Sun size={15}/><b>{brightness}%</b><button className="icon-btn" title="恢复 100%" onClick={()=>setReader({brightness:1})}><RefreshCw size={12}/></button></div></div><div className="settings-row"><span className="settings-label">字体</span><div className="settings-segments font-segments">{[["sans","黑体"],["serif","宋体"],["kai","楷体"]].map(([value,label])=><button key={value} className={reader.fontFamily===value?"active":""} onClick={()=>setReader({fontFamily:value})}>{label}</button>)}</div></div><div className="settings-row"><span className="settings-label">字号</span><div className="font-stepper"><button aria-label="减小字号" disabled={fontSize<=14} onClick={()=>setReader({fontSize:Math.max(14,fontSize-1)})}>A<sup>−</sup></button><strong>{fontSize}</strong><button aria-label="增大字号" disabled={fontSize>=32} onClick={()=>setReader({fontSize:Math.min(32,fontSize+1)})}>A<sup>+</sup></button></div></div><div className="settings-row"><span className="settings-label">宽度</span><div className="settings-pills">{[640,760,900,1100].map(value=><button key={value} className={Math.round(reader.paperWidth)===value?"active":""} onClick={()=>setReader({paperWidth:value})}>{value}</button>)}</div></div><div className="settings-row"><span className="settings-label">模式</span><div className="settings-segments"><button className={!paged?"active":""} onClick={()=>setPageMode(false)}>单栏滚动</button><button className={paged?"active":""} onClick={()=>setPageMode(true)}>双栏翻页</button></div></div><div className="settings-row"><span className="settings-label">行距</span><div className="settings-pills">{[[1.6,"紧凑"],[1.95,"舒适"],[2.2,"宽松"]].map(([value,label])=><button key={value} className={Math.abs(reader.lineHeight-Number(value))<.02?"active":""} onClick={()=>setReader({lineHeight:Number(value)})}>{label}</button>)}</div></div><div className="settings-row"><span className="settings-label">边距</span><div className="settings-pills">{[[40,"窄"],[56,"标准"],[72,"宽"]].map(([value,label])=><button key={value} className={Math.round(reader.pageMargin)===value?"active":""} onClick={()=>setReader({pageMargin:Number(value)})}>{label}</button>)}</div></div><div className="settings-row compact-toggle"><span className="settings-label">窗口置顶</span><button className={`settings-switch ${draft.alwaysOnTop?"on":""}`} role="switch" aria-checked={draft.alwaysOnTop} onClick={()=>update({...draft,alwaysOnTop:!draft.alwaysOnTop})}><i/></button></div></div><footer className="settings-actions"><button className="subtle-btn" onClick={close}>取消</button><button className="primary-btn" onClick={()=>onSave(draft,paged)}>应用</button></footer></section></div>}
function PromptDialog({title,placeholder,initial,onSubmit}:{title:string;placeholder?:string;initial?:string;onSubmit:(value:string|null)=>void}){
  const [value,setValue]=useState(initial||"");
  const ref=useRef<HTMLInputElement>(null);
  useEffect(()=>{const t=requestAnimationFrame(()=>{ref.current?.focus();ref.current?.select()});return()=>cancelAnimationFrame(t)},[]);
  return <div className="modal-backdrop"><div className="modal"><div className="modal-head"><div><span>熊猫阅读</span><h2>{title}</h2></div><button className="icon-btn" onClick={()=>onSubmit(null)}><X size={16}/></button></div><input className="prompt-input" ref={ref} value={value} placeholder={placeholder} onChange={e=>setValue(e.target.value)} onKeyDown={e=>{if(e.key==="Enter")onSubmit(value.trim()||null);if(e.key==="Escape")onSubmit(null)}}/><div className="modal-actions"><button className="subtle-btn" onClick={()=>onSubmit(null)}>取消</button><button className="primary-btn" onClick={()=>onSubmit(value.trim()||null)}>确定</button></div></div></div>
}
function TagsDialog({tags,suggestions,onSave,onClose}:{tags:string[];suggestions:string[];onSave:(tags:string[])=>Promise<string[]>;onClose:()=>void}){
  const [draft,setDraft]=useState(tags);
  const [input,setInput]=useState("");
  const [saving,setSaving]=useState(false);
  const ref=useRef<HTMLInputElement>(null);
  useEffect(()=>{const t=requestAnimationFrame(()=>ref.current?.focus());return()=>cancelAnimationFrame(t)},[]);
  const persist=async(next:string[])=>{if(saving)return;const previous=draft;setDraft(next);setSaving(true);try{setDraft(await onSave(next))}catch(e){setDraft(previous);toast.error(`标签保存失败：${errorText(e)}`)}finally{setSaving(false);requestAnimationFrame(()=>ref.current?.focus())}};
  const addTag=(value:string)=>{const tag=value.trim().replace(/^#+/,"").trim();if(!tag||saving)return;setInput("");if(draft.some(item=>item.toLowerCase()===tag.toLowerCase())){ref.current?.focus();return;}void persist([...draft,tag])};
  const removeTag=(tag:string)=>{if(!saving)void persist(draft.filter(item=>item!==tag))};
  const available=suggestions.filter(tag=>!draft.some(item=>item.toLowerCase()===tag.toLowerCase()));
  return <div className="modal-backdrop"><div className="modal"><div className="modal-head"><div><span>{saving?"正在保存":"标签即时保存"}</span><h2>管理小说标签</h2></div><button className="icon-btn" disabled={saving} onClick={onClose}><X size={16}/></button></div><div className="tag-list">{draft.map(t=><span key={t}>#{t}<button title="移除标签" disabled={saving} onClick={()=>removeTag(t)}><X size={10}/></button></span>)}</div>{draft.length===0&&<div className="tag-empty">还没有标签</div>}{available.length>0&&<div className="tag-suggestions"><small>已有标签</small><div>{available.map(tag=><button key={tag} disabled={saving} onClick={()=>addTag(tag)}>#{tag}</button>)}</div></div>}<div className="tag-input-row"><input className="prompt-input" ref={ref} value={input} disabled={saving} maxLength={32} placeholder="输入标签，如：重生" onChange={e=>setInput(e.target.value)} onKeyDown={e=>{if(e.key==="Enter"){e.preventDefault();addTag(input)}if(e.key==="Escape"&&!saving)onClose()}}/><button className="subtle-btn" disabled={saving||!input.trim()} onClick={()=>addTag(input)}>{saving?"保存中":"添加"}</button></div><div className="modal-actions"><button className="primary-btn" disabled={saving} onClick={onClose}>完成</button></div></div></div>
}
function ConflictBar({onReload,onSaveAs,onOverwrite}:{onReload:()=>void;onSaveAs:()=>void;onOverwrite:()=>void}){return <div className="conflict-bar"><strong>磁盘上的文稿已被其他程序修改</strong><span>自动保存已暂停，请选择如何处理当前编辑内容。</span><button onClick={onReload}>重新载入</button><button onClick={onSaveAs}>另存为</button><button className="danger" onClick={onOverwrite}>覆盖磁盘版本</button></div>}
function errorText(error:unknown){if(typeof error==="string")return error;if(error&&typeof error==="object"){if("message" in error)return String((error as {message:unknown}).message);const values=Object.values(error as Record<string,unknown>);if(values.length)return values.map(value=>typeof value==="string"?value:JSON.stringify(value)).join("：")}return "操作未完成"}
